module.exports = /*#__PURE__*/JSON.parse('{"Navigation":{"home":"Accueil","impressum":"Mentions légales","privacy":"Politique de confidentialité","contact":"Contact","language":"Langue","terms":"Conditions d\'utilisation"},"Meta":{"title":"Wildscope : Application d\'Identification de la Faune et d\'Exploration de la Nature avec IA","description":"Découvrez et identifiez la faune avec la technologie IA, explorez la nature avec des cartes hors ligne et suivez les animaux comme un pro. Votre compagnon ultime pour les aventures en pleine nature."},"Hero":{"title":"Votre Compagnon Outdoor Complet","subtitle":"Découvrez la faune, apprenez les techniques de survie et explorez la nature avec l\'identification par IA, une base de données mondiale d\'espèces et des guides interactifs.","appstore":"Télécharger sur l\'App Store","playstore":"Obtenir sur Google Play","download_subtext":"Téléchargement gratuit avec fonctionnalités premium disponibles","feature_1":"Reconnaissance IA de la Faune et Flore","feature_2":"Base de Données Mondiale d\'Espèces","feature_3":"Cartes et Navigation Hors Ligne","feature_4":"Techniques de Survie et Guides","feature_5":"Alertes Météo et Sécurité","feature_6":"Apprentissage Interactif et Communauté"},"About":{"title":"Votre Guide Complet d\'Identification de la Faune et de la Nature","paragraph1":"Vivez la nature comme jamais auparavant avec la technologie IA avancée de Wildscope. Que vous identifiiez des plantes lors d\'une randonnée, suiviez la faune dans des zones reculées ou découvriez les écosystèmes locaux, nos fonctionnalités complètes fonctionnent parfaitement en ligne et hors ligne.","paragraph2":"Des promenades nature occasionnelles au suivi sérieux de la faune, Wildscope combine une technologie IA de pointe avec des outils outdoor complets pour enrichir chaque expérience nature."},"Features":{"title":"Outils Complets d\'Identification et d\'Exploration de la Nature","feature1_title":"Reconnaissance Avancée des Espèces et Coach IA","feature1_desc":"Identifiez instantanément des milliers d\'espèces avec notre système de reconnaissance par IA et recevez des conseils personnalisés de votre guide nature IA. Le Coach Wildscope répond à vos questions sur votre environnement, fournit des conseils de sécurité et partage des connaissances fascinantes sur les espèces et écosystèmes locaux.","feature1_point1":"Identification en temps réel par IA","feature1_point2":"Guidage personnalisé par Coach IA","feature1_point3":"Alertes de sécurité contextuelles","feature2_title":"Navigation et Outils de Sécurité","feature2_desc":"Naviguez en toute confiance avec notre boîte à outils complète comprenant des cartes hors ligne, une navigation par boussole, des données météo et un système de points de repère. Parfait pour les aventures en zones reculées.","feature2_point1":"Boussole avec navigation par points","feature2_point2":"Mises à jour météo en temps réel","feature2_point3":"Accès aux informations d\'urgence","feature3_title":"Analyse d\'Habitat et Bio-Index","feature3_desc":"Explorez et comprenez les écosystèmes avec nos outils d\'analyse avancés. Suivez les indices de biodiversité, surveillez la distribution des espèces et découvrez les points chauds de la faune dans votre région.","feature3_point1":"Analyse d\'habitat et biomes","feature3_point2":"Suivi de l\'indice de biodiversité","feature3_point3":"Cartes de distribution des espèces","feature4_title":"Guide de Survie Complet","feature4_desc":"Maîtrisez les compétences essentielles en plein air avec nos guides de survie complets. Apprenez les nœuds, la construction d\'abris, l\'allumage de feu et d\'autres techniques cruciales de survie en milieu sauvage.","feature4_point1":"Tutoriels interactifs de nœuds","feature4_point2":"Techniques de construction d\'abris","feature4_point3":"Méthodes d\'allumage de feu","feature5_title":"Communauté Nature et Médias","feature5_desc":"Connectez-vous avec d\'autres passionnés de nature grâce à nos fonctionnalités communautaires dynamiques. Partagez vos découvertes, restez informé des actualités nature et participez aux défis communautaires.","feature5_point1":"Flux de photographie nature","feature5_point2":"Actualités faune et nature","feature5_point3":"Défis communautaires","feature6_title":"Expérience d\'Apprentissage Interactive","feature6_desc":"Apprenez et testez vos connaissances à travers des quiz captivants, des aventures guidées et des parcours d\'apprentissage personnalisés. Suivez vos progrès et gagnez des récompenses en maîtrisant les compétences outdoor.","feature6_point1":"Quiz d\'identification d\'espèces","feature6_point2":"Aventures nature guidées","feature6_point3":"Récompenses basées sur les compétences"},"OnlineFeatures":{"title":"Fonctionnalités En Ligne - Enrichies par l\'IA","intro":"Restez connecté pour l\'expérience complète :","feature1_title":"Coach Wildscope","feature1_desc":"Posez des questions sur votre environnement, téléchargez des images et recevez des conseils personnalisés.","feature2_title":"Identification Alimentée par l\'IA","feature2_desc":"Reconnaissez instantanément les espèces et accédez à des informations détaillées selon votre localisation.","feature3_title":"Analyses Intelligentes","feature3_desc":"Découvrez l\'histoire locale, les observations de la communauté, les tendances saisonnières et plus encore.","feature4_title":"Communauté Mondiale et Partage","feature4_desc":"Partagez vos découvertes, suivez les observations rares et explorez les sentiers créés par les utilisateurs.","feature5_title":"Quiz et Aventures Textuelles Géolocalisés","feature5_desc":"Interagissez avec votre environnement à travers des expériences riches et immersives."},"CallToAction":{"title":"Ne Manquez Plus Aucun Moment Incroyable avec la Faune !","subtitle":"Rejoignez des milliers de passionnés de nature qui découvrent et identifient déjà la faune comme jamais auparavant. Téléchargez Wildscope maintenant et transformez vos aventures en plein air !","appstore":"Télécharger sur l\'App Store","playstore":"Obtenir sur Google Play","button":"Commencez Votre Voyage Sauvage","playstoreLink":"https://play.google.com/store/apps/details?id=com.duselk.theoutdoorbible","benefits":["✓ Identification Instantanée des Plantes & Animaux","✓ Fonctionne Hors Ligne en Zones Reculées","✓ Navigation & Suivi GPS","✓ Guide Nature Alimenté par l\'IA","✓ Communauté Mondiale de la Faune"]},"Footer":{"copyright":"© {year} Wildscope. Tous droits réservés.","impressum":"Mentions Légales","privacy":"Politique de Confidentialité","contact":"Contact"},"CookieBanner":{"message":"Ce site web utilise des cookies pour vous garantir la meilleure expérience sur notre site.","accept":"Accepter","decline":"Refuser"},"ImpressumPage":{"title":"Mentions Légales","section1_title":"Information selon § 5 TMG (loi allemande)","address":"Dustin Keßler<br />Kurt Schumacher Straße 93<br />46539 Dinslaken<br />Allemagne","contact_title":"Contact","contact_email":"E-mail: ","responsibility_title":"Responsable du contenu selon § 55 para. 2 RStV (loi allemande)","disclaimer_title":"Clause de non-responsabilité","disclaimer_text":"Le contenu de notre site a été créé avec le plus grand soin. Cependant, nous ne pouvons garantir l\'exactitude, l\'exhaustivité et l\'actualité du contenu. En tant que fournisseur de services, nous sommes responsables de notre propre contenu sur ces pages selon les lois générales conformément au § 7 para. 1 TMG (loi allemande). Selon les §§ 8 à 10 TMG (loi allemande), en tant que fournisseur de services, nous ne sommes pas tenus de surveiller les informations transmises ou stockées par des tiers, ni d\'enquêter sur des circonstances qui indiquent une activité illégale."},"PrivacyPage":{"content":"# Politique de confidentialité pour Wildscope\\n\\n**Dernière mise à jour :** 06 février 2025\\n\\n## 2. Quelles données collectons-nous ?\\nLa plupart des données sont stockées localement sur votre appareil. Les données ne sont stockées dans le cloud ou sur des services externes que lorsque vous utilisez des fonctionnalités spécifiques.\\n\\n### 📍 Données de localisation et d\'activité\\n• La majeure partie du traitement de la localisation s\'effectue localement sur votre appareil.\\n• Nous stockons les pays, biomes, royaumes et écorégions visités dans votre profil utilisateur (sans données GPS ou de localisation exacte).\\n• Les données de localisation ne sont envoyées à des services externes que lorsque certaines fonctionnalités sont utilisées :\\n  - API Google Maps, Places et Geocoding : Cartes, autocomplétion et recherche de POI (Points d\'Intérêt).\\n  - Mapbox : Styles de carte, tuiles et navigation (utilisateurs Premium).\\n  - OpenStreetMap (OSM) : Recherche de POI et données cartographiques.\\n  - GBIF : Recherche d\'animaux et de plantes dans votre région.\\n  - OpenWeather & RainViewer : Données météorologiques et radar.\\n  - Open Elevation & OpenTopo : Analyse du terrain.\\n  - Google Gemini & OpenAI : Fonctionnalités d\'IA (ex: quiz, mode aventure).\\n\\n### 💾 Firebase pour le stockage et l\'authentification\\n\\n• Nous utilisons Firebase (région de Francfort) pour l\'authentification des utilisateurs et le stockage des données.\\n\\n• Des données telles que les comptes utilisateurs, les publications, les commentaires, les téléchargements et les régions visitées sont stockées dans Firebase.\\n\\n• Firebase met en œuvre ses propres contrôles de sécurité et d\'accès pour protéger vos données.\\n\\n• Vous pouvez demander la suppression complète de votre compte et des données associées à tout moment.\\n\\n### 📊 Analyses PostHog et utilisation de l\'application\\n\\n• Nous utilisons PostHog pour des statistiques d\'utilisation anonymisées.\\n\\n• PostHog nous aide à comprendre et à améliorer l\'utilisation de l\'application.\\n\\n• Les données collectées incluent : les écrans visités, les interactions avec l\'application, la durée de la session.\\n\\n• Aucune donnée personnelle n\'est liée à votre compte.\\n\\n• Vous pouvez désactiver le suivi à tout moment dans les paramètres.\\n\\n### 👤 Données du compte utilisateur et du profil\\n\\n• Inscription requise.\\n\\n• Stockage de : nom d\'utilisateur, adresse e-mail, statut premium.\\n\\n• Les mots de passe sont stockés de manière chiffrée.\\n\\n### 📤 Téléchargements et interactions\\nLes données ne sont stockées dans le cloud que lorsque vous :\\n\\n• Partagez une image ou une vidéo : Nom d\'utilisateur, date et lieu de la prise de vue.\\n\\n• Créez une publication : Le texte est stocké, mais pas votre localisation.\\n\\n• Aimez ou commentez : Seule l\'interaction elle-même est stockée.\\n\\n### 🎥 Services et API tiers\\n\\n• Cartes et localisation : Google Maps, Places, API de Geocoding et Mapbox (utilisateurs Premium).\\n\\n• Données sur la nature : GBIF pour les informations sur les espèces, PlantNet pour l\'identification des plantes.\\n\\n• Météo : OpenWeather et RainViewer pour les données météorologiques.\\n\\n• Terrain : Open Elevation et OpenTopo pour les données d\'altitude.\\n\\n• Contenu : Vidéos YouTube, articles et images de Wikipédia/Wikimedia.\\n\\n• Services d\'IA : Google Gemini et OpenAI pour les fonctionnalités interactives.\\n\\n• Chaque service traite les données conformément à ses propres politiques de confidentialité.\\n\\n• Les fonctionnalités Premium utilisent RevenueCat pour le traitement des paiements.\\n\\n### 📺 Utilisation des services de l\'API YouTube\\nNotre application utilise les services de l\'API YouTube pour vous fournir du contenu vidéo lié aux activités de plein air, à la nature et aux techniques de survie. En utilisant notre fonctionnalité de Fil Média, vous reconnaissez et acceptez d\'être lié par les Conditions d\'utilisation de YouTube (https://www.youtube.com/t/terms) et les Règles de confidentialité de Google (http://www.google.com/policies/privacy).\\n\\n#### Collecte et accès aux données\\nLorsque vous utilisez notre fonctionnalité de Fil Média, nous accédons et collectons les informations suivantes via les services de l\'API YouTube :\\n\\n**Depuis l\'API YouTube :**\\n\\n• Métadonnées vidéo publiques, y compris les titres, descriptions, miniatures, noms de chaîne et dates de publication.\\n• URL et identifiants de vidéos.\\n• Résultats de recherche basés sur votre localisation et les catégories de contenu sélectionnées.\\n\\n**Depuis votre appareil :**\\n\\n• Vos données de localisation (lorsque les flux basés sur la localisation sont activés) pour fournir un contenu vidéo géographiquement pertinent.\\n• Préférences et paramètres de l\'application stockés localement sur votre appareil.\\n• Données vidéo mises en cache temporairement dans le stockage local de votre appareil.\\n\\n#### Stockage et mise en cache des données\\n\\n• Les métadonnées vidéo récupérées de l\'API YouTube sont mises en cache localement sur votre appareil pour une durée maximale de 24 heures afin d\'améliorer les performances de l\'application et de réduire l\'utilisation des données.\\n\\n• Les données en cache comprennent les détails de la vidéo, les horodatages, les catégories sélectionnées, la portée de la localisation et les informations de localisation.\\n\\n• Aucune donnée d\'authentification de l\'utilisateur ou information personnelle du compte YouTube n\'est stockée.\\n\\n• Toutes les données mises en cache sont stockées localement sur votre appareil à l\'aide d\'AsyncStorage et ne sont pas transmises à des serveurs externes.\\n\\n#### Utilisation et traitement des données\\nNous utilisons les informations collectées pour :\\n\\n• Afficher du contenu vidéo pertinent sur le plein air et la nature dans notre Fil Média.\\n\\n• Fournir des recommandations vidéo basées sur la localisation lorsque vous activez les flux de localisation.\\n\\n• Mettre en cache le contenu localement pour améliorer les performances de l\'application et la capacité hors ligne.\\n\\n• Filtrer et trier les résultats vidéo en fonction de vos préférences et de votre localisation.\\n\\n#### Partage de données et tiers\\n\\n• Nous ne partageons aucune donnée d\'utilisateur ou de l\'API YouTube avec des tiers à des fins commerciales.\\n\\n• Les interactions vidéo au sein des lecteurs YouTube intégrés sont soumises aux propres pratiques de confidentialité de YouTube et peuvent être suivies par Google/YouTube.\\n\\n• Notre application utilise ses propres identifiants d\'API YouTube et n\'accède pas à votre compte YouTube personnel.\\n\\n• Les données de localisation utilisées pour les recherches de vidéos sont traitées localement et combinées avec des termes de recherche publics.\\n\\n#### Cookies et informations sur l\'appareil\\n\\n• Lors de la visualisation de vidéos YouTube intégrées, YouTube peut placer des cookies ou des technologies similaires sur votre appareil conformément aux pratiques de confidentialité de Google.\\n\\n• Notre application accède au stockage local de l\'appareil (AsyncStorage) pour mettre en cache le contenu vidéo et stocker les préférences de l\'utilisateur.\\n\\n• Nous pouvons collecter des informations sur l\'appareil nécessaires au fonctionnement de l\'application, y compris les données de localisation pour les fonctionnalités basées sur la localisation.\\n\\n#### Conservation des données\\n\\n• Les métadonnées vidéo mises en cache localement sont automatiquement supprimées après 24 heures.\\n\\n• Les préférences et paramètres de l\'utilisateur restent stockés localement jusqu\'à ce que vous désinstalliez l\'application ou effaciez manuellement les données de l\'application.\\n\\n• Aucune donnée de l\'API YouTube n\'est stockée de manière permanente sur des serveurs externes.\\n\\n#### Droits et contrôle de l\'utilisateur\\nVous pouvez :\\n\\n• Désactiver les flux vidéo basés sur la localisation dans les paramètres de l\'application.\\n• Effacer les données mises en cache en actualisant le Fil Média ou en vidant le stockage de l\'application.\\n• Accéder aux vidéos YouTube directement via l\'application ou le site web de YouTube, où les contrôles de confidentialité de Google s\'appliquent.\\n• Nous contacter pour demander des informations sur les données collectées via notre application.\\n\\n#### Politiques de confidentialité des tiers\\nEn utilisant les services de l\'API YouTube au sein de notre application, vous êtes également soumis à :\\n\\n• Règles de confidentialité de Google : http://www.google.com/policies/privacy\\n• Conditions d\'utilisation de YouTube : https://www.youtube.com/t/terms\\n\\n### 🤖 Consentement IA\\nCertaines fonctionnalités de cette application utilisent des services d\'IA fournis par OpenAI et/ou Google Gemini. Ces services peuvent traiter les données utilisateur en dehors de l\'UE. Aucune fonctionnalité d\'IA n\'est activée par défaut. En activant explicitement les fonctionnalités d\'IA dans l\'application, vous donnez votre consentement en vertu de l\'Art. 6(1)(a) du RGPD. Vous pouvez retirer ce consentement à tout moment via les paramètres de l\'application.\\n\\n## 3. Pourquoi traitons-nous vos données ?\\nBases légales selon le RGPD :\\n\\n• Art. 6(1)(a) (Consentement) : Partage de la localisation, utilisation de l\'IA, téléchargements.\\n\\n• Art. 6(1)(b) (Exécution du contrat) : Compte utilisateur et abonnement premium.\\n\\n• Art. 6(1)(f) (Intérêt légitime) : Amélioration de l\'application grâce aux analyses de PostHog.\\n\\n## 4. Stockage et suppression des données\\nOù sont stockées vos données ?\\n\\n• Données de localisation : Localement, non stockées de manière permanente.\\n\\n• Publications, \\"j\'aime\\", téléchargements : Dans Firebase (région de Francfort), si partagés activement.\\n\\n• Données d\'analyse : Anonymisées via PostHog.\\n\\n• La plupart des données de l\'application sont stockées localement sur votre appareil.\\n\\n• Serveurs backend : Situés aux États-Unis et en Europe (Heroku).\\n\\n• Identification des plantes : API PlantNet (service externe).\\n\\n• Fil d\'actualités : API Google News.\\n\\n• Traitement des paiements : RevenueCat (pas de stockage direct des données de paiement).\\n\\nSuppression des données :\\n\\n• Toutes les données peuvent être supprimées dans les paramètres de l\'application.\\n\\n• La suppression du compte entraîne la suppression de toutes les données liées dans Firebase.\\n\\n## 5. Qui a accès à vos données ?\\n\\n• Aucun partage à des fins publicitaires.\\n\\n• Les données de localisation ne sont envoyées que temporairement à des services externes.\\n\\n• YouTube et Wikimedia collectent leurs propres données lorsqu\'ils sont utilisés.\\n\\n• PostHog traite des statistiques d\'utilisation anonymes.\\n\\n• Les API de Google sont utilisées pour diverses fonctions.\\n\\n• Pas de stockage des données de paiement (Google Play / Apple Pay).\\n\\n## 6. Vos droits en vertu du RGPD\\n\\n• Information sur les données stockées.\\n\\n• Correction des données incorrectes.\\n\\n• Suppression de vos données.\\n\\n• Portabilité des données.\\n\\n• Retrait du consentement à tout moment.\\n\\n📧 Contact pour les questions de confidentialité : duselkay@gmail.com\\n\\n## 1. Responsable du traitement\\nDustin Keßler\\nAdresse : Kurt Schumacher Straße 93, 46539 Dinslaken\\nE-mail : duselkay@gmail.com"},"TermsPage":{"title":"Conditions d\'utilisation","content":"# Conditions d\'utilisation\\n\\nDernière mise à jour : 6 février 2025\\n\\n## 1. Généralités\\nLes présentes Conditions d\'utilisation régissent l\'utilisation de l\'application Wildscope. En créant un compte, vous acceptez ces conditions. L\'âge minimum requis est de 16 ans. L\'application propose des fonctions d\'observation de la faune, d\'identification des plantes et d\'exploration de la nature afin d\'enrichir votre expérience en plein air.\\n\\n## 2. Fonctionnalités de l\'application\\nWildscope fournit des données géolocalisées sur les animaux, les plantes, les points d\'intérêt et la météo. L\'application intègre des fonctionnalités basées sur l\'intelligence artificielle (quiz nature, mode aventure), permet de publier des photos et vidéos, de créer des publications, et d\'accéder à des contenus premium avec des fonctionnalités avancées.\\n\\n## 3. Compte utilisateur et responsabilité\\nVous êtes responsable de la sécurité de votre compte et de l\'utilisation d\'un mot de passe sécurisé. Les utilisateurs doivent respecter toutes les lois et réglementations en vigueur.\\n\\n### Contenus interdits\\nIl est interdit de publier du contenu illégal, offensant ou protégé par des droits d\'auteur. La manipulation des données de localisation est strictement interdite. Vous pouvez supprimer votre compte à tout moment via les paramètres de l\'application.\\n\\n## 4. Gestion technique des données\\nLa majorité des données est stockée localement sur votre appareil pour garantir performance et confidentialité. Firebase est utilisé pour l\'authentification et le stockage cloud si nécessaire. PostHog fournit des statistiques anonymisées pour améliorer l\'application. Les API de Google assurent diverses fonctions. Vos données ne sont jamais utilisées à des fins publicitaires.\\n\\n## 5. Abonnement Premium\\nLes fonctionnalités premium sont disponibles via Google Play ou Apple Pay. Il n\'y a pas de droit de rétractation après utilisation des fonctionnalités premium. L\'abonnement peut être annulé à tout moment via le store correspondant.\\n\\n## 6. Clause de non-responsabilité\\n### Limitation de responsabilité\\nNous déclinons toute responsabilité concernant :\\n• Des informations erronées ou obsolètes sur les plantes, animaux ou points d\'intérêt\\n• Les dommages résultant d\'une mauvaise utilisation des conseils ou contenus liés à la survie ou à la nature\\n• La perte de données, les dysfonctionnements ou l\'indisponibilité temporaire de fonctionnalités\\n• Les failles de sécurité liées à des services tiers\\n• Les contenus générés par l\'IA ou les décisions qui en découlent — toutes les sorties IA (texte, image, audio, suggestions) sont fournies sans garantie d\'exactitude ou d\'adéquation. Utilisation à vos risques et périls, en particulier dans des contextes de survie ou d\'urgence.\\n\\n### Contenus IA & situations d\'urgence\\nWildscope utilise des fonctionnalités expérimentales d\'IA, fournies par des tiers comme OpenAI ou Google Gemini. Ces outils peuvent générer des contenus inexacts, inadaptés ou trompeurs. Ne vous fiez pas aux contenus IA dans des situations critiques. Vous êtes seul responsable des décisions prises à partir de ces informations. Nous déclinons toute responsabilité liée à leur utilisation.\\n\\n## 7. Droits sur les contenus\\n### Contenus générés par l\'utilisateur\\nTous les contenus publiés ou créés par l\'utilisateur lui appartiennent. Ils sont privés par défaut, sauf indication contraire. Les contenus illégaux seront supprimés sans préavis.\\n\\n### Contenus de l\'application et droits d\'auteur\\nTous les contenus de l\'application (textes, données, graphiques, etc.) sont protégés par le droit d\'auteur. Toute utilisation commerciale sans autorisation écrite est interdite.\\n\\n## 8. Intégration de YouTube\\nNotre application intègre les services YouTube API pour proposer des vidéos. L\'utilisation de toute fonctionnalité liée à YouTube est soumise aux [Conditions d\'utilisation de YouTube](https://www.youtube.com/t/terms), intégrées aux présentes Conditions.\\n\\n### Utilisation autorisée\\nEn utilisant le Media Feed, vous vous engagez à :\\n• Respecter les Conditions d\'utilisation et les Règles de la communauté YouTube\\n• N\'utiliser les vidéos qu\'à des fins personnelles et non commerciales\\n• Ne pas télécharger, extraire ou redistribuer les contenus en dehors du cadre de l\'application\\n• Respecter les droits des créateurs de contenu et de YouTube\\n\\n### Clause de non-responsabilité liée à YouTube\\n• Nous ne sommes pas responsables de l\'exactitude, la légalité ou la pertinence des contenus affichés\\n• Les contenus proviennent de tiers et ne reflètent pas nécessairement nos opinions\\n• La disponibilité et les fonctionnalités de YouTube peuvent changer sans préavis\\n\\n### Traitement des données par YouTube\\nEn utilisant les services YouTube, vous acceptez que :\\n• Google/YouTube traitent vos données d\'interaction selon leur politique de confidentialité\\n• Les lecteurs intégrés puissent collecter des statistiques d\'utilisation\\n• Nous agissions en tant que sous-traitant de données sans contrôle sur les pratiques de YouTube\\n\\n## 9. Remboursements\\nTous les paiements sont gérés via le Google Play Store ou l\'Apple App Store. Les politiques de remboursement de ces plateformes s\'appliquent.\\n\\nAucun remboursement n\'est accordé en cas de :\\n• Fonctionnalités IA ou média indisponibles à cause de limites atteintes\\n• Problèmes temporaires liés aux services tiers\\n• Incompatibilité avec l\'appareil ou absence de connexion Internet\\n\\nL\'utilisateur est responsable de la gestion de son abonnement. Nous n\'avons pas accès aux systèmes de facturation des plateformes.\\n\\n## 10. Services tiers & limitations API\\nWildscope repose sur de nombreux services tiers soumis à des quotas, restrictions ou interruptions. Cela peut impacter aussi bien les utilisateurs gratuits que premium.\\n\\n**Services utilisés (exemples) :**\\n• API Google (Maps, Places, Geocoding, Static Maps)\\n• Mapbox (cartes, styles, navigation)\\n• PlantNet (identification de plantes)\\n• YouTube Data API\\n• API Wikipedia / Wikimedia\\n• OpenStreetMap / Overpass\\n• GBIF (biodiversité)\\n• RainViewer & OpenWeatherMap (météo, radar)\\n• Open Elevation & OpenTopo\\n• RevenueCat (paiements intégrés)\\n• Firebase (authentification, base de données, cloud)\\n• OpenAI & Google Gemini (IA)\\n\\nNous ne sommes pas responsables des interruptions ou limitations causées par ces services. Exemples :\\n• PlantNet limité à 500 requêtes/jour en gratuit\\n• Mapbox peut cesser ses services après dépassement du quota mensuel\\n• OpenAI/Gemini peuvent suspendre l\'accès selon la charge ou les coûts\\n\\n## 11. Mentions légales\\n• Aucune garantie n\'est fournie concernant l\'exactitude ou la fiabilité des contenus, conseils ou recommandations\\n• Toutes les fonctionnalités (IA, cartes, identification) sont à but informatif et ludique\\n• Wildscope n\'est pas un outil médical ou de survie certifié\\n• Vous devez respecter la législation locale lors de l\'utilisation de données de localisation, d\'espèces ou lors de la publication de contenus\\n\\n## 12. Modifications des Conditions\\nContinuer à utiliser l\'application après une mise à jour des Conditions implique votre acceptation des nouvelles règles. Vous serez informé(e) des changements majeurs via l\'application ou par email.\\n\\n## 13. Contact\\nPour toute question ou demande de support : duselkay@gmail.com"},"ContactPage":{"title":"Contact","contact_intro":"N\'hésitez pas à nous contacter pour toute question, commentaire ou demande.","contact_person":"Personne à contacter","country":"Allemagne"},"NotFound":{"title":"Page Non Trouvée","description":"Désolé, la page que vous recherchez n\'existe pas ou a été déplacée.","backHome":"Retour à la Page d\'Accueil"},"General":{"loading":"Chargement...","comingSoon":"Bientôt disponible"},"FAQ":{"title":"Questions Fréquemment Posées sur le Suivi de la Faune","question1":"Comment Wildscope se compare-t-il à d\'autres applications d\'identification de la nature comme iNaturalist?","answer1":"Alors qu\'iNaturalist se concentre principalement sur l\'identification des espèces et la science citoyenne, Wildscope offre une expérience en plein air complète avec des fonctionnalités supplémentaires spécifiquement conçues pour les amoureux de la nature. Notre application comprend l\'identification de la faune hors ligne, des outils de navigation GPS pour l\'exploration en pleine nature, l\'apprentissage interactif à travers des quiz sur la nature, et un compagnon IA qui comprend votre environnement pour fournir des conseils personnalisés—ce qui la rend parfaite tant pour les amateurs occasionnels de nature que pour les traqueurs sérieux de la faune.","question2":"Puis-je identifier des plantes et des animaux hors ligne avec Wildscope?","answer2":"Partiellement. L\'analyse par IA nécessite une connexion Internet, mais vous verrez toutes les espèces suivies de votre région affichées et pourrez les utiliser pour faciliter l\'identification.","question3":"Quels appareils prennent en charge l\'application d\'exploration de la nature Wildscope?","answer3":"Les fonctionnalités de suivi de la faune et d\'identification de la nature de Wildscope sont disponibles à la fois pour les appareils iOS (iPhone/iPad) et Android via l\'App Store et le Google Play Store, ce qui la rend accessible pour pratiquement tous les utilisateurs de smartphones.","question4":"L\'application d\'identification de la faune Wildscope est-elle gratuite?","answer4":"Wildscope offre une version gratuite avec des fonctionnalités essentielles d\'identification de la faune et d\'exploration de la nature. Notre abonnement premium débloque des capacités avancées comme des trouvailles d\'espèces illimitées, plus de crédits, plus de lieux personnalisés à visiter, et des avantages supplémentaires. Consultez l\'application pour connaître les options d\'abonnement actuelles.","question5":"Quelle est la précision de l\'identification des plantes et des animaux de Wildscope?","answer5":"Wildscope combine des données de localisation avec une technologie IA avancée pour identifier la faune et les plantes avec une grande précision. Bien que notre système de reconnaissance s\'améliore continuellement, la précision d\'identification varie selon l\'espèce, la qualité de l\'image et l\'angle de vision. Nous améliorons constamment nos algorithmes grâce à des mises à jour régulières pour fournir une identification de plus en plus précise de la faune et des plantes dans tous les environnements.","question6":"Puis-je contribuer à la base de données de la faune de Wildscope?","answer6":"Absolument! Wildscope prospère grâce aux contributions de la communauté. Vos observations de la faune et identifications de plantes sont ajoutées en toute sécurité à notre base de données d\'écosystème, améliorant la précision de l\'application pour tous. Cette approche collaborative crée une ressource complète d\'identification de la faune qui bénéficie à tous les amoureux de la nature.","question7":"Wildscope est-il développé par une grande entreprise technologique?","answer7":"Non, Wildscope est un projet indépendant développé par un passionné de nature dévoué. L\'application est conçue et maintenue par un seul développeur passionné qui privilégie la précision et l\'expérience utilisateur plutôt que la monétisation. Cette approche indépendante garantit que Wildscope reste fidèle à sa mission fondamentale: aider les gens à se connecter et à comprendre la nature sans compromettre la confidentialité ou l\'expérience de l\'utilisateur."},"Audience":{"title":"À Qui s\'Adresse Wildscope ?","intro":"Que vous soyez un explorateur chevronné ou que vous commenciez tout juste votre voyage dans la nature, Wildscope est conçu pour vous :","audience1_title":"Randonneurs & Trekkeurs","audience1_desc":"Naviguez sur les sentiers, identifiez les espèces et restez en sécurité avec des cartes hors ligne et des outils de survie.","audience2_title":"Photographes Animaliers & Ornithologues","audience2_desc":"Découvrez, suivez et identifiez les espèces insaisissables pour capturer la photo parfaite.","audience3_title":"Familles & Explorateurs Occasionnels","audience3_desc":"Transformez les visites de parcs en aventures d\'apprentissage passionnantes pour tous les âges.","audience4_title":"Éducateurs & Étudiants","audience4_desc":"Un outil puissant pour l\'éducation en plein air, les projets de biodiversité et les études naturalistes.","audience5_title":"Survivalistes & Adeptes du Bushcraft","audience5_desc":"Perfectionnez vos compétences avec l\'identification des plantes, les guides de construction d\'abris et les ressources hors ligne.","conclusion":"Et toute personne curieuse du monde naturel !"},"Testimonials":{"title":"Ce que disent nos Explorateurs","testimonial1":"Wildscope a complètement changé ma façon d\'explorer. Les cartes hors ligne sont une bouée de sauvetage, et l\'identification par IA est incroyablement précise !","testimonial1_author":"Sarah L.","testimonial1_role":"Passionnée de Randonnée","testimonial2":"En tant que professeur de biologie, cette application est un outil fantastique pour mes étudiants. Elle rend l\'apprentissage de la flore et de la faune locales tellement plus interactif.","testimonial2_author":"David K.","testimonial2_role":"Éducateur"},"Pricing":{"title":"Choisissez Votre Plan Wildscope","free_title":"Explorateur Basique","free_subtitle":"Commencez votre voyage avec les fonctionnalités essentielles.","free_price":"Gratuit","free_price_suffix":"Pour toujours","free_feature1":"Identification IA des espèces (limitée)","free_feature2":"Cartes régionales hors ligne (1 région)","free_feature3":"Accès au guide de survie de base","free_feature4":"Accès au forum communautaire","free_feature5":"Suivre 5 POI favoris","free_feature_limited1":"Expérience avec publicité","free_cta":"Inclus avec le téléchargement","pro_badge":"Meilleur Prix","pro_title":"Wildscope Pro","pro_subtitle":"Libérez toute la puissance de l\'exploration de la nature.","pro_price":"2,99 €","pro_price_suffix":"par mois (ou 17,99 €/an)","pro_feature1":"Identification IA illimitée des espèces","pro_feature2":"Cartes régionales hors ligne illimitées","pro_feature3":"Guide de survie complet & outils avancés","pro_feature4":"Fonctionnalités communautaires Premium","pro_feature5":"Suivre un nombre illimité de POI favoris","pro_feature6":"Expérience sans publicité","pro_feature7":"Support prioritaire","pro_cta":"Passez Pro & Explorez Plus","footnote":"Les prix peuvent varier selon la région. Abonnements gérés via l\'App Store/Google Play."}}');

